const e=JSON.parse(JSON.stringify($json));
const decision=e.decision??{};
const blocked=decision.block_delivery===true;
const optedOut=decision.route==='DND';
const effectiveSend=decision.send_user_response===true&&!blocked&&!optedOut;
const skippedReason=blocked?'BLOCK_DELIVERY':optedOut?'DND':decision.send_user_response!==true?'SEND_USER_RESPONSE_FALSE_OR_MISSING':'ROUTING_GUARD';
const warning='GENERATION_SKIPPED_'+skippedReason;
e.response={candidate:{sms_response:null,email_subject:null,email_body:null,booking_date:null,booking_time:null},generation:{attempted:false,model:null,status:'skipped',skipped_reason:skippedReason,effective_send_user_response:effectiveSend,warning,warnings:[warning],allowed_links_by_type:{vdp:null,trade:null,finance:null,booking:null,store_website:null}}};
return [{json:e}];

const e=JSON.parse(JSON.stringify($node['Sub-workflow Input'].json));
const decision=e.decision??{};
const f=decision.allowed_facts??{};
const inv=f.inventory??{};
const blocked=decision.block_delivery===true;
const optedOut=decision.route==='DND';
const effectiveSend=decision.send_user_response===true&&!blocked&&!optedOut;
const linkKeys=['vdp','trade','finance','booking','store_website'];
const sourceLinks=f.links&&typeof f.links==='object'&&!Array.isArray(f.links)?f.links:{};
const links=Object.fromEntries(linkKeys.map(key=>[key,typeof sourceLinks[key]==='string'&&sourceLinks[key].trim()?sourceLinks[key].trim():null]));
const warnings=[];
const skippedReason=blocked?'BLOCK_DELIVERY':optedOut?'DND':decision.send_user_response!==true?'SEND_USER_RESPONSE_FALSE_OR_MISSING':null;
if(!effectiveSend){
  const warning='GENERATION_SKIPPED_'+skippedReason;
  e.response={candidate:{sms_response:null,email_subject:null,email_body:null,booking_date:null,booking_time:null},generation:{attempted:false,model:null,status:'skipped',skipped_reason:skippedReason,effective_send_user_response:false,warning,warnings:[warning],allowed_links_by_type:links}};
  return [{json:e}];
}
const raw=$json.output??$json.text??$json.content?.[0]?.text??'';
const apiFailure=$json.error!=null||$json.errorMessage!=null||$json.executionError!=null;
let parsed=null;
if(apiFailure)warnings.push('MODEL_CALL_FAILED');
else{
  try{
    const clean=String(raw).replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim();
    const start=clean.indexOf('{'),end=clean.lastIndexOf('}');
    parsed=JSON.parse(start>=0&&end>=start?clean.slice(start,end+1):clean);
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed)||!['sms_response','email_subject','email_body','booking_date','booking_time'].some(key=>Object.prototype.hasOwnProperty.call(parsed,key))){parsed=null;warnings.push('MODEL_RESPONSE_SCHEMA_INVALID');}
  }catch(error){warnings.push('MALFORMED_RESPONSE_JSON');}
}
const text=value=>value===null||value===undefined?null:String(value).trim()||null;
const approvedDate=text(f.appointment?.date);
const approvedTime=text(f.appointment?.time);
const vehicle=[f.vehicle?.year,f.vehicle?.make,f.vehicle?.model].filter(Boolean).join(' ');
const appointmentFallback=()=>{
  const confirmed=decision.route==='BOOKING'&&(f.appointment?.signal==='BOOKED'||e.intelligence?.appointment?.signal==='BOOKED');
  if(approvedDate&&approvedTime)return confirmed?'Your appointment is set for '+approvedDate+' at '+approvedTime+'.':'We have '+approvedDate+' at '+approvedTime+' for your visit. Would you like us to confirm that slot?';
  if(approvedDate)return 'What time works for your visit on '+approvedDate+'?';
  if(approvedTime)return 'What day works for a '+approvedTime+' visit?';
  return 'What day and time work best for your visit?';
};
const safeFallbackSms=()=>{
  if(decision.route==='ESCALATION')return 'Thanks for your message. A member of our dealership team will connect with you shortly to assist.';
  if(decision.route==='INVENTORY'){
    if(decision.inventory_claim_mode==='confirmed_available')return 'The '+(vehicle||'vehicle')+' is available. Would you like more details?';
    if(decision.inventory_claim_mode==='confirmed_unavailable')return 'The '+(vehicle||'vehicle')+" isn't currently available. Would you like help with alternatives?";
    if(decision.inventory_claim_mode==='alternatives_only')return 'We found similar options. Would you like the details?';
    if(decision.inventory_claim_mode==='no_match')return "We couldn't confirm a matching vehicle. Would you like help with alternatives?";
    if(vehicle)return 'We found the '+vehicle+', but its availability still needs to be confirmed.';
    return 'Which vehicle are you interested in? Please share the make and model.';
  }
  if(decision.route==='VISIT'||decision.route==='BOOKING')return appointmentFallback();
  if(decision.route==='GENERAL')return 'Thanks for your message. How can we help?';
  return null;
};
const fallbackCandidate=()=>decision.route==='EMAIL_HANDOFF'?{sms_response:null,email_subject:'Your AutoPulse dealership inquiry',email_body:'<p>Thanks for your message. Our dealership team will follow up about your inquiry.</p>',booking_date:approvedDate,booking_time:approvedTime}:{sms_response:safeFallbackSms(),email_subject:null,email_body:null,booking_date:approvedDate,booking_time:approvedTime};
let usedFallback=!parsed;
let candidate=parsed??fallbackCandidate();
const placeholderToKey={VDP_LINK:'vdp',TRADE_LINK:'trade',FINANCE_LINK:'finance',BOOKING_LINK:'booking',STORE_WEBSITE_LINK:'store_website'};
const sanitize=value=>{
  if(value===null||value===undefined)return null;
  const withoutLiteralUrls=String(value).replace(/https?:\/\/[^\s<>"']+/gi,match=>{
    const core=match.replace(/[),.;!?]+$/,'');
    const suffix=match.slice(core.length);
    warnings.push('MODEL_LITERAL_URL_REMOVED:'+core);
    return suffix;
  });
  return withoutLiteralUrls.replace(/\[(VDP_LINK|TRADE_LINK|FINANCE_LINK|BOOKING_LINK|STORE_WEBSITE_LINK)\]/gi,(token,label)=>{
    const key=placeholderToKey[label.toUpperCase()];
    if(links[key])return links[key];
    warnings.push('MISSING_LABELED_LINK:'+key);
    return '';
  }).replace(/\s{2,}/g,' ').trim()||null;
};
let sms=sanitize(candidate.sms_response);
let emailSubject=sanitize(candidate.email_subject);
let emailBody=sanitize(candidate.email_body);
if(decision.route==='EMAIL_HANDOFF'){
  sms=null;
  if(!emailBody){candidate=fallbackCandidate();emailSubject=candidate.email_subject;emailBody=candidate.email_body;usedFallback=true;warnings.push('MODEL_EMAIL_BODY_MISSING');}
}else{
  emailSubject=null;emailBody=null;
  if(!sms){sms=safeFallbackSms();usedFallback=true;warnings.push('MODEL_SMS_MISSING');}
}
const requestedMax=Number(decision.max_characters);
const maxCharacters=Number.isFinite(requestedMax)&&requestedMax>0?Math.floor(requestedMax):300;
const length=value=>String(value??'').length;
if(sms&&length(sms)>maxCharacters){
  warnings.push('SMS_RESPONSE_OVER_LIMIT');
  const replacement=safeFallbackSms();
  if(replacement&&length(replacement)<=maxCharacters){sms=replacement;usedFallback=true;warnings.push('OVER_LIMIT_RESPONSE_REPLACED_WITH_SAFE_FALLBACK');}
  else{sms=null;usedFallback=true;warnings.push('SMS_OVER_LIMIT_NO_SAFE_FALLBACK');}
}
const generationFailed=decision.route!=='EMAIL_HANDOFF'&&!sms;
const status=generationFailed?'failed':usedFallback?'fallback':'generated';
const warning=warnings[0]??null;
e.response={candidate:{sms_response:sms,email_subject:emailSubject,email_body:emailBody,booking_date:approvedDate,booking_time:approvedTime},generation:{attempted:true,model:'gpt-5.6-luna',status,skipped_reason:null,effective_send_user_response:true,max_characters:maxCharacters,warning,warnings:[...new Set(warnings)],allowed_links_by_type:links}};
return [{json:e}];
